#include "mirror_shim.h"

#include <atomic>

#include <QtCore/QCoreApplication>
#include <QtCore/QEventLoop>
#include <QtCore/QTimer>
#include <QtCore/QUrl>
#include <QtCore/QVariant>
#include <QtNetwork/QNetworkAccessManager>
#include <QtNetwork/QNetworkReply>
#include <QtNetwork/QNetworkRequest>

// Generated by cxx-qt-build from `src/mirror_model.rs`.
#include "khaxbps-qt/src/mirror_model.cxxqt.h"

namespace {

// One manager per probe batch. Qt keeps the socket notifiers of a manager in
// the thread that created it, so this object must live and die on the batch
// thread — which is exactly what the Rust worker does.
struct Prober
{
    QNetworkAccessManager manager;
};

// Set by `QCoreApplication::aboutToQuit`. A batch is up to 34 sequential
// requests, so without this a window closed mid-sweep would keep the worker (and
// its manager) alive for minutes after the GUI thread has gone.
std::atomic<bool> g_quitRequested{false};
std::atomic<bool> g_quitHooked{false};

// How often a blocked request looks at the shutdown flag.
constexpr int POLL_INTERVAL_MS = 50;

// Connects the quit signal once, on the thread that starts the first batch.
// `QObject::connect` is thread-safe and the lambda runs on the GUI thread, which
// is where `aboutToQuit` is emitted.
void hook_shutdown()
{
    if (g_quitHooked.exchange(true)) {
        return;
    }
    if (auto *app = QCoreApplication::instance()) {
        QObject::connect(app, &QCoreApplication::aboutToQuit, app, []() {
            g_quitRequested.store(true);
        });
    }
}

} // namespace

QObject *khaxbps_create_mirror_model(QObject *parent)
{
    return new MirrorModel(parent);
}

void khaxbps_mirror_model_set_all_running(QObject *model)
{
    static_cast<MirrorModel *>(model)->setAllRunning();
}

void khaxbps_mirror_model_finish_running(QObject *model)
{
    static_cast<MirrorModel *>(model)->finishRunning();
}

void khaxbps_mirror_model_set_result(QObject *model,
                                     int row,
                                     const QString &stateKey,
                                     std::uint32_t latencyMs,
                                     const QString &errorKey)
{
    static_cast<MirrorModel *>(model)->setResult(row, stateKey, latencyMs, errorKey);
}

std::size_t khaxbps_probe_batch_begin()
{
    hook_shutdown();
    return reinterpret_cast<std::size_t>(new Prober());
}

bool khaxbps_probe_shutdown_requested()
{
    return g_quitRequested.load();
}

void khaxbps_probe_batch_end(std::size_t handle)
{
    if (!handle) {
        return;
    }
    // Replies are deleted through `deleteLater`, so flush the deferred deletes
    // before the manager they belong to goes away.
    QCoreApplication::sendPostedEvents(nullptr, QEvent::DeferredDelete);
    delete reinterpret_cast<Prober *>(handle);
}

int khaxbps_probe_head(std::size_t handle, const QString &url, std::uint32_t timeoutMs)
{
    auto *prober = reinterpret_cast<Prober *>(handle);
    if (!prober) {
        return 2;
    }
    if (g_quitRequested.load()) {
        // Shutting down: do not open a socket at all.
        return 3;
    }

    QNetworkRequest request{QUrl(url)};
    // A mirror that redirects to another HTTPS host is fine; one that would
    // downgrade to plain HTTP is refused by Qt, like a browser.
    request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,
                         QNetworkRequest::NoLessSafeRedirectPolicy);
    request.setHeader(QNetworkRequest::UserAgentHeader, QStringLiteral("khaxbps/0.1"));
    const int timeout = static_cast<int>(qMin<std::uint32_t>(timeoutMs, 60000));
    // Total budget is the timer below; this only stops a socket that stalls
    // without ever finishing.
    request.setTransferTimeout(timeout);

    QNetworkReply *reply = prober->manager.head(request);
    if (!reply) {
        return 2;
    }

    QEventLoop loop;
    QTimer timer;
    timer.setSingleShot(true);
    QObject::connect(reply, &QNetworkReply::finished, &loop, &QEventLoop::quit);
    QObject::connect(&timer, &QTimer::timeout, &loop, &QEventLoop::quit);
    // Shutdown must not wait for the slowest mirror.
    QTimer poll;
    poll.setInterval(POLL_INTERVAL_MS);
    QObject::connect(&poll, &QTimer::timeout, &loop, [&loop]() {
        if (g_quitRequested.load()) {
            loop.quit();
        }
    });
    timer.start(timeout);
    poll.start();
    if (!reply->isFinished()) {
        loop.exec();
    }

    if (g_quitRequested.load()) {
        reply->abort();
        reply->deleteLater();
        return 3;
    }

    int result = 2;
    if (!reply->isFinished()) {
        // The timer won: the mirror did not answer in time.
        result = 1;
    } else if (reply->error() == QNetworkReply::OperationCanceledError
               || reply->error() == QNetworkReply::TimeoutError) {
        result = 1;
    } else if (reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).isValid()) {
        // Any HTTP status is an answer: the web app's `fetch` resolves on a 404
        // as well, so only a failure to reach the mirror is an error here.
        result = 0;
    }

    reply->abort();
    reply->deleteLater();
    return result;
}
